const LEAF = "M0 0C-4-5.5-12-5.5-17 0C-12 5.5-4 5.5 0 0Z";
const STAR = "M0-5L1.2-1.6L4.8-1.5L1.9.6L2.9 4L0 2L-2.9 4L-1.9.6L-4.8-1.5L-1.2-1.6Z";
const STARS: [number, number][] = [[17, 121], [223, 121], [68.6, 85.3], [78.5, 73.9], [90.9, 65.3], [105, 59.8], [120, 58], [135, 59.8], [149.1, 65.3], [161.5, 73.9], [171.4, 85.3]];
const LEAF_TURNS = [16, 30, 44, 58, 72, 86];

/** The fleet's number in a ring. Decorative: the name beside it carries the meaning. */
export function Roundel({ size = 36, muted = false, className }: { size?: number; muted?: boolean; className?: string }) {
  return (
    <svg className={className} viewBox="0 0 200 200" width={size} height={size} aria-hidden="true" focusable="false">
      <circle cx="100" cy="100" r="93" fill="#0b111d" stroke={muted ? "#8d949f" : "#c8a45a"} strokeWidth={muted ? 6 : 7} />
      <path d={IX_MARK} fill={muted ? "#b6bfcd" : "#f6f3ea"} />
    </svg>
  );
}

function Branch() {
  return (
    <g fill="#c8a45a">
      <path d="M106 194A75 75 0 0 1 46.1 107" fill="none" stroke="#c8a45a" strokeWidth="1.4" />
      {LEAF_TURNS.map((turn) => (
        <g key={turn} transform={`rotate(${turn} 120 120)`}>
          <path d={LEAF} transform="translate(120 195) rotate(26)" />
          <path d={LEAF} transform="translate(120 195) rotate(-26)" />
        </g>
      ))}
      <g transform="rotate(100 120 120)">
        <path d={LEAF} transform="translate(120 195) rotate(8)" />
      </g>
    </g>
  );
}

/** The fleet crest: IX under nine stars, inside a laurel wreath and a gold ring. */
export function Crest({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 240 240"
      role="img"
      aria-label="The fleet crest: the numeral nine under nine stars, inside a laurel wreath and a gold ring"
    >
      <circle cx="120" cy="120" r="118" fill="#07112a" stroke="#c8a45a" strokeWidth="2.5" />
      <circle cx="120" cy="120" r="113" fill="none" stroke="#c8a45a" strokeWidth=".8" />
      <circle cx="120" cy="120" r="93" fill="#0d2148" stroke="#c8a45a" strokeWidth="1.6" />
      <circle cx="120" cy="120" r="89" fill="none" stroke="#c8a45a" strokeOpacity=".55" strokeWidth=".8" />
      <path d={RING_TOP} fill="#f0dfb4" />
      <path d={RING_BOTTOM} fill="#f0dfb4" />
      <g fill="#c8a45a">
        {STARS.map(([x, y]) => (
          <path key={`${x} ${y}`} d={STAR} transform={`translate(${x} ${y})`} />
        ))}
      </g>
      <Branch />
      <g transform="translate(240 0) scale(-1 1)">
        <Branch />
      </g>
      <path d={IX_CREST} fill="#f6f3ea" />
    </svg>
  );
}
